t = int(input())
for i in range(t):
	n = int(input())
	l = []
	for j in range(1, int(n ** 0.5) + 1):
		if n % j == 0:
			s1 = ''
			s2 = ''
			s1 += str(j)
			s2 += str(n // j)
			if s1.find('4') != -1 or s1.find('7') != -1:
				l.append(s1)
			if s2.find('4') != -1 or s2.find('7') != -1:
				l.append(s2)
	ans = set(l)
	print(len(ans))
